s=s.replace('  if (typeof row.details === "string") {', '  if (typeof secure.details === "string") {',1).replace('      const parsed = JSON.parse(row.details);', '      const parsed = JSON.parse(secure.details);',1)
s=s.replace('    scale_id: row.scale_id,\n    scale_name: row.scale_name,', '    scale_id: secure.scale_id,\n    scale_name: secure.scale_name,',1)
s=s.replace('.all();\n    const data = (rows.results ?? []).map(presentResult);', '.all();\n    const data = await Promise.all((rows.results ?? []).map((row) => presentResult(env, row)));',1)
s=s.replace('  } catch (error) {\n    console.error("[patient-results.GET]", error);', '  } catch (error) {\n    if (error instanceof ClinicalCryptoError) return errorResponse(error.message, error.code, 503);\n    console.error("[patient-results.GET]", error);',1)
p.write_text(s)

# Memory search: blind index + authorized decrypt; legacy fallback only before strict.
Path('functions/api/memory/search.ts').write_text(r'''/** Busca de memória clínica: índice cego HMAC + descriptografia autorizada. */
import type { ClinicalCryptoEnv } from "../_clinicalCrypto";
import { ClinicalCryptoError, clinicalStrictMode, searchEncryptedEntityIds } from "../_clinicalCrypto";
import { readMemoryPayload } from "../_clinicalRecords";
import { getContextUser, isAdmin } from "../auth/_authorization";
interface Env extends ClinicalCryptoEnv {DB?:D1Database;AI?:Ai;VECTORIZE?:Vectorize}
interface MemoryNote{id:string;title:string|null;content:string;category:string|null;source:string|null;tags:string|null;created_at:string;score?:number}
const LIMITS={query:300,category:80,results:20}as const;
function validationError(message:string){return Response.json({error:message,code:"VALIDATION_ERROR"},{status:400,headers:{"Cache-Control":"no-store"}})}function parseLimit(v:string|null){if(v===null)return 10;if(!/^\d+$/.test(v))return null;const n=Number(v);return Number.isSafeInteger(n)?Math.min(LIMITS.results,Math.max(1,n)):null}function parseScore(v:string|null){if(v===null)return .05;if(v.trim()==="")return null;const n=Number(v);return Number.isFinite(n)&&n>=0&&n<=1?n:null}
const DEMO_NOTES:MemoryNote[]=[{id:"mem-demo-001",title:"M-CHAT-R/F — Pontos de corte",content:"M-CHAT-R/F: Score 0-2 = baixo risco; 3-7 = risco moderado; 8-20 = risco elevado.",category:"escala",source:"manual_mchat",tags:'["mchat","tea","triagem","autismo"]',created_at:new Date("2025-01-01").toISOString()},{id:"mem-demo-002",title:"SNAP-IV — Interpretação clínica",content:"SNAP-IV: material demonstrativo.",category:"escala",source:"manual_snap",tags:'["snap","tdah"]',created_at:new Date("2025-01-01").toISOString()}];
function tokenize(t:string){return t.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9\s]/g," ").split(/\s+/).filter(x=>x.length>2)}function tf(term:string,tokens:string[]){return tokens.filter(t=>t===term).length/(tokens.length||1)}function boost(q:string,t:string){const n=(x:string)=>x.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"");return n(t).includes(n(q))?.5:0}function score(q:string,note:MemoryNote){const qs=tokenize(q);if(!qs.length)return 0;let tags="";try{const p=note.tags?JSON.parse(note.tags):[];if(Array.isArray(p))tags=p.filter((x):x is string=>typeof x==="string").join(" ")}catch{}const fields=[[note.title??"",3],[note.content,1],[note.category??"",2],[tags,1.5]]as const;let total=0;for(const[text,w]of fields){const ts=tokenize(text);for(const qx of qs)total+=tf(qx,ts)*w;total+=boost(q,text)*w}return Math.min(1,total/(qs.length*7.5+3.75))}
export const onRequestGet:PagesFunction<Env>=async(context)=>{const{request,env}=context;const url=new URL(request.url);const query=url.searchParams.get("q")?.trim()??"";const limit=parseLimit(url.searchParams.get("limit"));const category=url.searchParams.get("category")?.trim()||null;const minScore=parseScore(url.searchParams.get("min_score"));if(!query)return validationError("Parâmetro 'q' é obrigatório.");if(query.length>LIMITS.query)return validationError("'q' excede o limite.");if(category&&category.length>LIMITS.category)return validationError("'category' excede o limite.");if(limit===null)return validationError("'limit' deve ser inteiro válido.");if(minScore===null)return validationError("'min_score' deve estar entre 0 e 1.");if(!env.DB){const results=DEMO_NOTES.filter(n=>!category||n.category===category).map(n=>({...n,score:score(query,n)})).filter(n=>n.score>=minScore).sort((a,b)=>b.score-a.score).slice(0,limit);return Response.json({results,total:results.length,query,category,searchType:"text_tfidf",semanticSearchStatus:"not_configured"},{headers:{"Cache-Control":"no-store"}})}const user=getContextUser(context);if(!user)return Response.json({error:"Não autenticado.",code:"UNAUTHENTICATED"},{status:401,headers:{"Cache-Control":"no-store"}});try{let ids=await searchEncryptedEntityIds(env,env.DB,"memory_note","memory_search",query,5000);let rows:Record<string,unknown>[]=[];if(ids.length){const ph=ids.map(()=>"?").join(",");const owner=isAdmin(user)?"":`AND patient_id IN (SELECT id FROM patients_demo WHERE owner_user_id=? AND is_demo=1)`;const binds:unknown[]=[...ids,...(isAdmin(user)?[]:[user.id])];const res=await env.DB.prepare(`SELECT id,patient_id,title,content,category,source,tags,created_at,is_demo FROM memory_notes WHERE is_demo=1 AND id IN (${ph}) ${owner}`).bind(...binds).all<Record<string,unknown>>();rows=res.results??[]}else if(!clinicalStrictMode(env)){const owner=isAdmin(user)?"":`AND patient_id IN (SELECT id FROM patients_demo WHERE owner_user_id=? AND is_demo=1)`;const binds=isAdmin(user)?[]:[user.id];const res=await env.DB.prepare(`SELECT id,patient_id,title,content,category,source,tags,created_at,is_demo FROM memory_notes WHERE is_demo=1 ${owner} LIMIT 500`).bind(...binds).all<Record<string,unknown>>();rows=res.results??[]}const notes=await Promise.all(rows.map(async row=>{const p=await readMemoryPayload(env,row);return{id:String(row.id),...p,created_at:String(row.created_at??"")}as MemoryNote}));const results=notes.filter(n=>!category||n.category===category).map(n=>({...n,score:score(query,n)})).filter(n=>n.score>=minScore).sort((a,b)=>b.score-a.score).slice(0,limit);return Response.json({results,total:results.length,query,category,searchType:"blind_index_tfidf",semanticSearchStatus:"not_configured",searchStatusNote:"Candidatos via índice cego HMAC; ranking após descriptografia autorizada em memória."},{headers:{"Cache-Control":"no-store"}})}catch(error){if(error instanceof ClinicalCryptoError)return Response.json({error:error.message,code:error.code},{status:503,headers:{"Cache-Control":"no-store"}});console.error("[memory/search] error");return Response.json({error:"Erro ao buscar memória clínica.",code:"MEMORY_SEARCH_ERROR"},{status:500,headers:{"Cache-Control":"no-store"}})}};
''')

# Clinical Core encrypted semantic payload.
Path('functions/api/clinical-core/index.ts').write_text(r'''import { clinicalEventInputSchema, clinicalEventTypes, type ClinicalEvent, type ClinicalEventStatus, type ClinicalEventType } from "../../../shared/clinical-core";
import type { ClinicalCryptoEnv } from "../_clinicalCrypto";import { ClinicalCryptoError } from "../_clinicalCrypto";import { clinicalEventStorage, readClinicalEventPayload } from "../_clinicalRecords";import { canWriteClinicalData,getContextUser,getPatientAccess } from "../auth/_authorization";import { ensureClinicalCoreDemoSchema } from "./_schema";
interface Env extends ClinicalCryptoEnv{DB?:D1Database}interface Row{id:string;patient_id:string;author_user_id:string|null;event_type:string;occurred_at:string;encounter_id:string|null;provenance_kind:string;provenance_source:string;payload_json:string;supersedes_event_id:string|null;status:ClinicalEventStatus;created_at:string}
function json(data:unknown,status=200){return new Response(JSON.stringify(data),{status,headers:{"Content-Type":"application/json","Cache-Control":"no-store"}})}function error(message:string,code:string,status:number){return json({error:message,code},status)}function parseTypes(raw:string|null):ClinicalEventType[]|null{if(!raw)return[];const u=[...new Set(raw.split(",").map(x=>x.trim()).filter(Boolean))];if(u.length>clinicalEventTypes.length||u.some(x=>!clinicalEventTypes.includes(x as ClinicalEventType)))return null;return u as ClinicalEventType[]}
async function present(env:Env,row:Row):Promise<ClinicalEvent|null>{try{const secure=await readClinicalEventPayload(env,row as unknown as Record<string,unknown>);const p=JSON.parse(secure.payload_json)as{data:ClinicalEvent["data"];note?:string;sourceLabel?:string;capturedAt?:string};const parsed=clinicalEventInputSchema.safeParse({patientId:row.patient_id,eventType:secure.event_type,occurredAt:row.occurred_at,...(secure.encounter_id?{encounterId:secure.encounter_id}:{}),provenance:{kind:secure.provenance_kind,source:secure.provenance_source,...(p.sourceLabel?{sourceLabel:p.sourceLabel}:{}),...(p.capturedAt?{capturedAt:p.capturedAt}:{})},...(p.note?{note:p.note}:{}),...(row.supersedes_event_id?{supersedesEventId:row.supersedes_event_id}:{}),data:p.data});if(!parsed.success)return null;return{id:row.id,...parsed.data,authorUserId:row.author_user_id,status:row.status,createdAt:row.created_at,storageMode:"demo-db"}}catch(error){if(error instanceof ClinicalCryptoError)throw error;return null}}
export const onRequestGet:PagesFunction<Env>=async(context)=>{const{env,request}=context;if(!env.DB)return json({data:[],total:0,mode:"unavailable",reason:"Banco clínico não configurado."});const user=getContextUser(context);if(!user)return error("Não autenticado.","UNAUTHENTICATED",401);const url=new URL(request.url);const patientId=url.searchParams.get("patient_id")?.trim()??"";if(!patientId||patientId.length>128)return error("patient_id inválido.","VALIDATION_ERROR",400);const access=await getPatientAccess(env.DB,patientId,user);if(!access.exists)return error("Paciente não encontrado.","NOT_FOUND",404);if(!access.allowed)return error("Sem permissão para este paciente.","FORBIDDEN",403);const rawDays=Number(url.searchParams.get("days")??365);const days=Number.isFinite(rawDays)?Math.min(3650,Math.max(1,Math.round(rawDays))):365;const types=parseTypes(url.searchParams.get("types"));if(types==null)return error("types inválido.","VALIDATION_ERROR",400);const cutoff=new Date(Date.now()-days*86400000).toISOString();try{await ensureClinicalCoreDemoSchema(env.DB);const result=await env.DB.prepare(`SELECT id,patient_id,author_user_id,event_type,occurred_at,encounter_id,provenance_kind,provenance_source,payload_json,supersedes_event_id,status,created_at FROM clinical_events_demo WHERE patient_id=? AND is_demo=1 AND occurred_at>=? ORDER BY occurred_at DESC LIMIT 2000`).bind(patientId,cutoff).all<Row>();const all=(await Promise.all((result.results??[]).map(row=>present(env,row)))).filter((x):x is ClinicalEvent=>x!=null);const data=types.length?all.filter(x=>types.includes(x.eventType)):all;return json({data,total:data.length,mode:"demo-db"})}catch(cause){if(cause instanceof ClinicalCryptoError)return error(cause.message,cause.code,503);console.error("[clinical-core.GET]");return error("Não foi possível carregar a linha clínica.","DB_ERROR",500)}};
export const onRequestPost:PagesFunction<Env>=async(context)=>{const{env,request}=context;if(!env.DB)return error("Registro remoto indisponível. Nenhum dado foi simulado.","STORAGE_UNAVAILABLE",503);const user=getContextUser(context);if(!user)return error("Não autenticado.","UNAUTHENTICATED",401);if(!canWriteClinicalData(user))return error("Perfil sem permissão para registrar eventos clínicos.","FORBIDDEN",403);let body:unknown;try{body=await request.json()}catch{return error("Corpo JSON inválido.","INVALID_JSON",400)}const parsed=clinicalEventInputSchema.safeParse(body);if(!parsed.success)return json({error:"Evento clínico inválido.",code:"VALIDATION_ERROR",details:parsed.error.issues},400);const input=parsed.data;const access=await getPatientAccess(env.DB,input.patientId,user);if(!access.exists)return error("Paciente não encontrado.","NOT_FOUND",404);if(!access.allowed)return error("Sem permissão para este paciente.","FORBIDDEN",403);try{await ensureClinicalCoreDemoSchema(env.DB);if(input.supersedesEventId){const prev=await env.DB.prepare("SELECT id,patient_id,status FROM clinical_events_demo WHERE id=? AND is_demo=1 LIMIT 1").bind(input.supersedesEventId).first<{id:string;patient_id:string;status:string}>();if(!prev||prev.patient_id!==input.patientId||prev.status!=="active")return error("Evento supersedido inválido ou já corrigido.","INVALID_SUPERSESSION",409)}const id=`clinical-${crypto.randomUUID()}`;const createdAt=new Date().toISOString();const clear=JSON.stringify({data:input.data,...(input.note?{note:input.note}:{}),...(input.provenance.sourceLabel?{sourceLabel:input.provenance.sourceLabel}:{}),...(input.provenance.capturedAt?{capturedAt:input.provenance.capturedAt}:{})});const envelope=await clinicalEventStorage(env,id,input.patientId,{event_type:input.eventType,encounter_id:input.encounterId??null,provenance_kind:input.provenance.kind,provenance_source:input.provenance.source,payload_json:clear});const statements=[] as D1PreparedStatement[];if(input.supersedesEventId)statements.push(env.DB.prepare("UPDATE clinical_events_demo SET status='corrected' WHERE id=? AND patient_id=? AND is_demo=1 AND status='active'").bind(input.supersedesEventId,input.patientId));statements.push(env.DB.prepare(`INSERT INTO clinical_events_demo(id,patient_id,author_user_id,event_type,occurred_at,encounter_id,provenance_kind,provenance_source,payload_json,supersedes_event_id,status,is_demo,created_at) VALUES(?,?,?,'observation',?,NULL,'documented','encrypted',?,?,'active',1,?)`).bind(id,input.patientId,user.id,input.occurredAt,envelope,input.supersedesEventId??null,createdAt));const results=await env.DB.batch(statements);if(input.supersedesEventId&&!results[0]?.meta.changes){await env.DB.prepare("DELETE FROM clinical_events_demo WHERE id=?").bind(id).run();return error("Evento foi alterado por outra requisição.","STALE_CLINICAL_EVENT",409)}return json({id,...input,authorUserId:user.id,status:"active",createdAt,storageMode:"demo-db"}as ClinicalEvent,201)}catch(cause){if(cause instanceof ClinicalCryptoError)return error(cause.message,cause.code,503);console.error("[clinical-core.POST]");return error("Não foi possível salvar o evento clínico.","DB_ERROR",500)}};
''')

# Conecta encrypted event semantics.
Path('functions/api/conecta/index.ts').write_text(r'''import { conectaEventInputSchema,type ConectaEvent } from "../../../shared/conecta";import type { ClinicalCryptoEnv } from "../_clinicalCrypto";import { ClinicalCryptoError } from "../_clinicalCrypto";import { conectaStorage,readConectaPayload } from "../_clinicalRecords";import { canWriteClinicalData,getContextUser,getPatientAccess } from "../auth/_authorization";import { ensureConectaDemoSchema } from "./_schema";
interface Env extends ClinicalCryptoEnv{DB?:D1Database}interface Row{id:string;patient_id:string;author_user_id:string|null;category:string;occurred_at:string;context:string|null;value:number|null;duration_minutes:number|null;payload_json:string|null;created_at:string}
function json(data:unknown,status=200){return new Response(JSON.stringify(data),{status,headers:{"Content-Type":"application/json","Cache-Control":"no-store"}})}function error(message:string,code:string,status:number){return json({error:message,code},status)}async function present(env:Env,row:Row):Promise<ConectaEvent>{const s=await readConectaPayload(env,row as unknown as Record<string,unknown>);let extra:Pick<ConectaEvent,"note"|"detail">={};if(s.payload_json)try{const p=JSON.parse(s.payload_json);if(p&&typeof p==="object")extra=p}catch{}return{id:row.id,patientId:row.patient_id,authorUserId:row.author_user_id,category:s.category as ConectaEvent["category"],occurredAt:row.occurred_at,...(s.context?{context:s.context as ConectaEvent["context"]}:{}),...(typeof s.value==="number"?{value:s.value}:{}),...(typeof s.duration_minutes==="number"?{durationMinutes:s.duration_minutes}:{}),...extra,createdAt:row.created_at,storageMode:"demo-db"}}
export const onRequestGet:PagesFunction<Env>=async(context)=>{const{env,request}=context;if(!env.DB)return json({data:[],total:0,mode:"unavailable",reason:"Banco clínico não configurado."});const user=getContextUser(context);if(!user)return error("Não autenticado.","UNAUTHENTICATED",401);const url=new URL(request.url);const patientId=url.searchParams.get("patient_id")?.trim()??"";const raw=Number(url.searchParams.get("days")??90);const days=Number.isFinite(raw)?Math.min(365,Math.max(1,Math.round(raw))):90;if(!patientId||patientId.length>128)return error("patient_id inválido.","VALIDATION_ERROR",400);const access=await getPatientAccess(env.DB,patientId,user);if(!access.exists)return error("Paciente não encontrado.","NOT_FOUND",404);if(!access.allowed)return error("Sem permissão para este paciente.","FORBIDDEN",403);const cutoff=new Date(Date.now()-days*86400000).toISOString();try{await ensureConectaDemoSchema(env.DB);const r=await env.DB.prepare(`SELECT id,patient_id,author_user_id,category,occurred_at,context,value,duration_minutes,payload_json,created_at FROM conecta_events_demo WHERE patient_id=? AND is_demo=1 AND occurred_at>=? ORDER BY occurred_at DESC LIMIT 1000`).bind(patientId,cutoff).all<Row>();const data=await Promise.all((r.results??[]).map(row=>present(env,row)));return json({data,total:data.length,mode:"demo-db"})}catch(cause){if(cause instanceof ClinicalCryptoError)return error(cause.message,cause.code,503);console.error("[conecta.GET]");return error("Não foi possível carregar os registros agora.","DB_ERROR",500)}};
export const onRequestPost:PagesFunction<Env>=async(context)=>{const{env,request}=context;if(!env.DB)return error("Registro remoto indisponível. Nenhum dado foi simulado.","STORAGE_UNAVAILABLE",503);const user=getContextUser(context);if(!user)return error("Não autenticado.","UNAUTHENTICATED",401);if(!canWriteClinicalData(user))return error("Perfil sem permissão para registrar eventos.","FORBIDDEN",403);let body:unknown;try{body=await request.json()}catch{return error("Corpo JSON inválido.","INVALID_JSON",400)}const parsed=conectaEventInputSchema.safeParse(body);if(!parsed.success)return json({error:"Registro inválido.",code:"VALIDATION_ERROR",details:parsed.error.issues},400);const access=await getPatientAccess(env.DB,parsed.data.patientId,user);if(!access.exists)return error("Paciente não encontrado.","NOT_FOUND",404);if(!access.allowed)return error("Sem permissão para este paciente.","FORBIDDEN",403);const id=`conecta-${crypto.randomUUID()}`;const createdAt=new Date().toISOString();try{await ensureConectaDemoSchema(env.DB);const clear=parsed.data.note||parsed.data.detail?JSON.stringify({note:parsed.data.note,detail:parsed.data.detail}):null;const envelope=await conectaStorage(env,id,parsed.data.patientId,{category:parsed.data.category,context:parsed.data.context??null,value:parsed.data.value??null,duration_minutes:parsed.data.durationMinutes??null,payload_json:clear});await env.DB.prepare(`INSERT INTO conecta_events_demo(id,patient_id,author_user_id,category,occurred_at,context,value,duration_minutes,payload_json,is_demo,created_at) VALUES(?,?,?,'encrypted',?,NULL,NULL,NULL,?,1,?)`).bind(id,parsed.data.patientId,user.id,parsed.data.occurredAt,envelope,createdAt).run();return json({id,...parsed.data,authorUserId:user.id,createdAt,storageMode:"demo-db"}as ConectaEvent,201)}catch(cause){if(cause instanceof ClinicalCryptoError)return error(cause.message,cause.code,503);console.error("[conecta.POST]");return error("Não foi possível salvar o registro.","DB_ERROR",500)}};
''')

